<script module lang="ts">
/**
 * The page outside the shell: sign-in, sign-up, a setup step, a status (`design/archetypes/auth-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/auth-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import { PageTransition, joinSlot, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/archetypes/auth-page.module.css'
import transitions from '@polymorph/recipes/conventions/page-transitions.module.css'
import Card from '../structure/Card.svelte'

export interface AuthPageProps {
  /**
   * An accessible back control, when this step has a return destination.
   */
  backAction?: Snippet
  /**
   * The product's wordmark, centred above the card.
   */
  brand?: Snippet
  /**
   * The line under the actions, inside the card (the login block's structure), such as "Don't
   * have an account? Sign up". It is inside the card, not under it, which is why it is a
   * separate slot. A sentence offering the other account action belongs to the form it is an
   * alternative to. Below the card it would float on the background, detached from the form.
   * `footer` keeps the outside position for page-level links.
   */
  cardFooter?: Snippet
  /**
   * FormFields and the submit Button. On a status page, the notice and the actions. Omitted when
   * the title and description say everything and the reader has nothing to do here.
   */
  children?: Snippet
  description?: Snippet
  /**
   * A row of Links below the card, such as legal, support or a locale switch.
   */
  footer?: Snippet
  illustration?: Snippet
  /**
   * The layout, where `illustrated` is the public account layout with host-supplied artwork.
   */
  layout?: 'centered' | 'illustrated'
  pending?: boolean
  /**
   * The `<h1>`.
   */
  title: string
  transitionKey?: string
}
</script>

<script lang="ts">
let {
  backAction,
  brand,
  cardFooter,
  children,
  description,
  footer,
  illustration,
  layout = 'centered',
  pending = false,
  title,
  transitionKey,
}: AuthPageProps = $props()
const joined = joinSlot(undefined, () => ({}))
const slots = {
  get backAction() {
    return backAction
  },
  get brand() {
    return brand
  },
  get cardFooter() {
    return cardFooter
  },
  get default() {
    return children
  },
  get description() {
    return description
  },
  get footer() {
    return footer
  },
  get illustration() {
    return illustration
  },
}
let body = $state<HTMLElement | null>(null)
const illustrated = $derived(layout === 'illustrated')
const effect1 = () => {
  illustrated &&
    body
      ?.querySelectorAll('[data-auth-enter]')
      .forEach((item, index) =>
        (item as HTMLElement).style.setProperty(
          '--pm-page-enter-order',
          String(Math.min(index, 9)),
        ),
      )
}
watchEffect(effect1, { watch: () => [illustrated, transitionKey] })
</script>

{@render joined.start?.()
}{#if joined.shown
  }<main
    class={[styles.page, illustrated ? styles.illustrated : undefined]}
    aria-busy={pending ? true : undefined}
    data-auth-layout={layout}
    data-member="auth-page"
    >{#if illustrated && slots.brand}<div class={styles.topbar}>{@render brand?.()}</div>{/if
    }<div bind:this={body} class={styles.body}
      ><PageTransition
        class={[styles.column, transitionKey !== undefined ? transitions.page : undefined]}
        as="div"
        {transitionKey}
        {pending}
        ribbon={transitions.indicator}
        >{#if illustrated && slots.illustration
          }<div class={styles.illustration} aria-hidden="true">{@render illustration?.()}</div
        >{/if
        }<div class={styles.formColumn}
          >{#if !illustrated && slots.brand}<div class={styles.brand}>{@render brand?.()}</div>{/if
          }{#if illustrated
            }<div class={styles.frame}
              ><div class={styles.card}
                ><div class={styles.heading} data-auth-enter=""
                  ><div class={[styles.titleRow, slots.backAction ? styles.withBack : undefined]}
                    >{#if slots.backAction
                      }<div class={styles.backAction}>{@render backAction?.()}</div
                    >{/if
                    }<h1 class={styles.title}>{title}</h1
                  ></div
                  >{#if slots.description
                    }<p class={styles.description}>{@render description?.()}</p
                  >{/if
                }</div
                >{@render children?.()
                }{#if slots.cardFooter
                  }<div class={styles.cardFooter}>{@render cardFooter?.()}</div
                >{/if
              }</div
            ></div
          >{:else
            }<Card
              ><div class={styles.card}
                ><div class={styles.heading} data-auth-enter=""
                  ><div class={[styles.titleRow, slots.backAction ? styles.withBack : undefined]}
                    >{#if slots.backAction
                      }<div class={styles.backAction}>{@render backAction?.()}</div
                    >{/if
                    }<h1 class={styles.title}>{title}</h1
                  ></div
                  >{#if slots.description
                    }<p class={styles.description}>{@render description?.()}</p
                  >{/if
                }</div
                >{@render children?.()
                }{#if slots.cardFooter
                  }<div class={styles.cardFooter}>{@render cardFooter?.()}</div
                >{/if
              }</div
            ></Card
          >{/if
          }{#if slots.footer}<div class={styles.footer}>{@render footer?.()}</div>{/if
        }</div
      ></PageTransition
    ></div
  ></main
>{/if
}{@render joined.end?.()}
